import com.alipay.antchain.bridge.commons.core.am.AuthMessageFactory;
import com.alipay.antchain.bridge.commons.core.am.IAuthMessage;
import com.alipay.antchain.bridge.commons.core.monitor.IMonitorMessage;
import com.alipay.antchain.bridge.commons.core.monitor.MonitorMessageFactory;
import com.alipay.antchain.bridge.commons.core.sdp.ISDPMessage;
import com.alipay.antchain.bridge.commons.core.sdp.SDPMessageFactory;
import com.alipay.antchain.bridge.commons.core.base.*;

import cn.hutool.core.util.HexUtil;


public class UcpParser {

    public static void main(String[] args) {

        String rawUcpHex = "";

        byte[] rawUcp = HexUtil.decodeHex(rawUcpHex);

        UniformCrosschainPacket ucp = UniformCrosschainPacket.decode(rawUcp);

        IAuthMessage authMessage =
                AuthMessageFactory.createAuthMessage(
                        ucp.getSrcMessage().getMessage());

        ISDPMessage sdpMessage =
                SDPMessageFactory.createSDPMessage(
                        authMessage.getPayload());

        IMonitorMessage monitorMessage =
                MonitorMessageFactory.createMonitorMessage(
                        sdpMessage.getPayload());


        // 部署的环境：
        // 链域名：eth01（以太坊测试链），diox01 (课题一提供的dioxide测试链) pluginserver名称：ps01，委员会committee名称: ptc01
        // 委员会节点：三个普通节点node1～3，一个监管节点monitor-node
        // 部署的示例应用合约为
          // [dioxide]AntChainBridge/acb-sdk/pluginset/dioxide/onchain-plugin/AppContract.gcl
          // [ethereum2]AntChainBridge/acb-sdk/pluginset/ethereum2/onchain-plugin/solidity/sys/AppContract.sol

        // 从diox01发送无序消息到eth01，消息内容为"0x313132323333"，关闭监管
        // 打印了部分字段以供参考
        // 期望结果：
        // authMessage.getVersion: 1(AM合约消息版本)
        // authMessage.getUpperProtocol: 0(上层协议类型，0表示SDP合约)
        // authMessage.getIdentity: 000000000000000000000000000000000000000000000000000003f301200001(from地址 此处为dioxide上合约cid的32字节表示)
        // sdpMessage.getTargetDomain: eth01(目的链域名，唯一标识目的链。发送链域名也在ucp中, 但不在authMessage中)
        // sdpMessage.getTargetIdentity: 0000000000000000000000006db20c530b3f96cd5ef64da2b1b931cb8f264009(to地址 此处为以太坊测试链上合约地址的32字节表示)
        // sdpMessage.getSequence: -1(消息序列号，-1标识无序消息)
        // monitorMessage.getMonitorType: 1(监管字段标识，表示dioxide不开启监管)
        // monitorMessage.getMonitorMsg: 876543(测试解析用 无含义)
        // monitorMessage.getPayload: 0x313132323333(应用合约发送的消息内容的十六进制表示)
        System.out.println(
                "authMessage.getVersion: " + authMessage.getVersion() + "\n" +
                "authMessage.getUpperProtocol: " + authMessage.getUpperProtocol() + "\n" +
                "authMessage.getIdentity: " + authMessage.getIdentity().toHex() + "\n" +
                "sdpMessage.getTargetDomain: " + sdpMessage.getTargetDomain().getDomain() + "\n" +
                "sdpMessage.getTargetIdentity: " + sdpMessage.getTargetIdentity().toHex() + "\n" +
                "sdpMessage.getSequence: " + sdpMessage.getSequence() + "\n" +
                "monitorMessage.getMonitorType: " + monitorMessage.getMonitorType() + "\n" +
                "monitorMessage.getMonitorMsg: " + monitorMessage.getMonitorMsg() + "\n" +
                "monitorMessage.getPayload: 0x" + HexUtil.encodeHexStr(monitorMessage.getPayload())
                );

        // 以下ucp实例是从eth01发送无序消息到diox01，消息内容为"0x313233"，开启监管
        // 
    }
}

